def _make_case_class(metadata: dict, class_name: str):
    class GeneratedCOExecutableCase(A2AExecutableCase):
        def __init__(self) -> None:
            super().__init__(metadata)

    GeneratedCOExecutableCase.__name__ = class_name
    GeneratedCOExecutableCase.__qualname__ = class_name
    return GeneratedCOExecutableCase


for _index, _metadata in enumerate(CASE_METADATA, start=1):
    if _metadata.get('is_control'):
        _class_name = f"COControl{_index - 100:03d}"
    else:
        _class_name = f"COEval{_index:03d}"
    globals()[_class_name] = _make_case_class(_metadata, _class_name)

